package main

import (
 "fmt"
 "net"
 "time"
 "golang.org/x/net/icmp"
 "golang.org/x/net/ipv4"
)

func main(){
 c, err := icmp.ListenPacket("udp4", "0.0.0.0")
 if err != nil {
   fmt.Printf("err: %v\n", err)
   return
 }
 defer c.Close()
 fmt.Printf("local=%v\n", c.LocalAddr())
 // Try with ID = local port vs random
 // Get local port
 udpAddr := c.LocalAddr().(*net.UDPAddr)
 fmt.Printf("local port=%d\n", udpAddr.Port)
 for _, id := range []int{udpAddr.Port, 123, 9999} {
   dst, _ := net.ResolveUDPAddr("udp4", "127.0.0.1:0")
   wm := icmp.Message{Type: ipv4.ICMPTypeEcho, Code: 0, Body: &icmp.Echo{ID: id, Seq: 0, Data: []byte("hello world test data")}}
   wb, _ := wm.Marshal(nil)
   fmt.Printf("sending with ID=%d...\n", id)
   n, err := c.WriteTo(wb, dst)
   fmt.Printf("WriteTo n=%d err=%v\n", n, err)
   if err != nil { continue }
   // Try read with timeout
   c.SetReadDeadline(time.Now().Add(2*time.Second))
   rb := make([]byte, 1500)
   n, peer, err := c.ReadFrom(rb)
   fmt.Printf("ReadFrom n=%d peer=%v err=%v\n", n, peer, err)
   if err == nil {
     rm, err := icmp.ParseMessage(1, rb[:n])
     fmt.Printf("parsed type=%v code=%d err=%v body=%T\n", rm.Type, rm.Code, err, rm.Body)
     if echo, ok := rm.Body.(*icmp.Echo); ok {
       fmt.Printf("echo ID=%d Seq=%d Data=%q\n", echo.ID, echo.Seq, string(echo.Data))
     }
   }
 }
}
EOF
cd /tmp/icmptest2 && GOPROXY=off GOTOOLCHAIN=go1.25.11 go run . 2>&1
"}

