package main

import (
 "encoding/binary"
 "fmt"
 "net"
 "syscall"
 "time"
 "os"
)

func checksum(data []byte) uint16 {
 sum := uint32(0)
 for i := 0; i < len(data)-1; i += 2 {
   sum += uint32(binary.BigEndian.Uint16(data[i:]))
 }
 if len(data)%2 == 1 {
   sum += uint32(data[len(data)-1]) << 8
 }
 sum = (sum >> 16) + (sum & 0xffff)
 sum += sum >> 16
 return uint16(^sum)
}

func main(){
 // Create ping socket: AF_INET, SOCK_DGRAM, IPPROTO_ICMP (1)
 fd, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, 1)
 if err != nil {
   fmt.Printf("Socket err: %v\n", err)
   os.Exit(1)
 }
 defer syscall.Close(fd)
 fmt.Printf("fd=%d\n", fd)
 // Bind to 0.0.0.0:0
 addr := &syscall.SockaddrInet4{Port: 0, Addr: [4]byte{0,0,0,0}}
 if err := syscall.Bind(fd, addr); err != nil {
   fmt.Printf("Bind err: %v\n", err)
   os.Exit(1)
 }
 // Getsockname
 sa, err := syscall.Getsockname(fd)
 if err != nil {
   fmt.Printf("Getsockname err: %v\n", err)
 } else {
   fmt.Printf("Getsockname: %#v\n", sa)
   if a, ok := sa.(*syscall.SockaddrInet4); ok {
     fmt.Printf("bound port=%d addr=%v\n", a.Port, a.Addr)
   }
 }
 // Enable IP_RECVTTL
 if err := syscall.SetsockoptInt(fd, syscall.IPPROTO_IP, syscall.IP_RECVTTL, 1); err != nil {
   fmt.Printf("Setsockopt IP_RECVTTL err: %v\n", err)
 } else {
   fmt.Printf("Setsockopt ok\n")
 }
 // Build ICMP echo: type 8, code 0, checksum, id, seq, data(24)
 // Get id = bound port?
 // For now use bound port
 var id uint16
 if a, ok := sa.(*syscall.SockaddrInet4); ok {
   id = uint16(a.Port)
 }
 fmt.Printf("using id=%d\n", id)
 pkt := make([]byte, 32)
 pkt[0] = 8 // echo
 pkt[1] = 0
 // checksum placeholder
 binary.BigEndian.PutUint16(pkt[4:], id)
 binary.BigEndian.PutUint16(pkt[6:], 0)
 // data 24 bytes zeros
 csum := checksum(pkt)
 binary.BigEndian.PutUint16(pkt[2:], csum)
 fmt.Printf("sending %d bytes csum=%x\n", len(pkt), csum)
 dst := &syscall.SockaddrInet4{Port: 0, Addr: [4]byte{127,0,0,1}}
 if err := syscall.Sendto(fd, pkt, 0, dst); err != nil {
   fmt.Printf("Sendto err: %v\n", err)
   // Try to wrap like net.OpError?
   if opErr, ok := err.(*net.OpError); ok {
     fmt.Printf("OpError: %v\n", opErr)
   } else {
     fmt.Printf("raw err type %T\n", err)
     // Create OpError manually
     laddr := &net.UDPAddr{IP: net.IPv4(0,0,0,0), Port: int(id)}
     raddr := &net.UDPAddr{IP: net.IPv4(127,0,0,1), Port: 0}
     op := &net.OpError{Op: "write", Net: "udp", Source: laddr, Addr: raddr, Err: err}
     fmt.Printf("wrapped: %v\n", op)
   }
   os.Exit(1)
 }
 fmt.Printf("sent\n")
 // Set timeout via SetReadDeadline? For syscall, use Select or Set timeout via SO_RCVTIMEO?
 tv := syscall.NsecToTimeval((2 * time.Second).Nanoseconds())
   syscall.SetsockoptTimeval(fd, syscall.SOL_SOCKET, syscall.SO_RCVTIMEO, &tv)
 // Recvmsg with control
 buf := make([]byte, 1500)
 oob := make([]byte, 1024)
 n, oobn, _, from, err := syscall.Recvmsg(fd, buf, oob, 0)
 if err != nil {
   fmt.Printf("Recvmsg err: %v\n", err)
   os.Exit(1)
 }
 fmt.Printf("Recvmsg n=%d oobn=%d from=%#v\n", n, oobn, from)
 fmt.Printf("data: %v\n", buf[:n])
 if n >= 8 {
   fmt.Printf("type=%d code=%d id=%d seq=%d\n", buf[0], buf[1], binary.BigEndian.Uint16(buf[4:]), binary.BigEndian.Uint16(buf[6:]))
 }
 if oobn > 0 {
   fmt.Printf("oob: %v\n", oob[:oobn])
   cmsgs, err := syscall.ParseSocketControlMessage(oob[:oobn])
   fmt.Printf("cmsgs err=%v n=%d\n", err, len(cmsgs))
   for i, m := range cmsgs {
     fmt.Printf("cmsg %d: header=%#v data=%v\n", i, m.Header, m.Data)
   }
 }
}
EOF
